  /* Spec section 7: a program may SUGGEST priority lifts; installing must not
     impose them. Only fill them in while they are still the untouched default —
     a lifter who has chosen their own competition lifts keeps them. */
  const stock = ['back-squat', 'bench-press', 'deadlift'];
  const untouched = (S.settings.priority || []).every((p, i) =>
    typeof p === 'string' ? p === ['Back Squat', 'Bench Press', 'Deadlift'][i]
                          : !!(p && p.leaf && p.leaf.movement === stock[i]));
  if (P.priority && untouched) {
    S.settings.priority = P.priority.slice(0, 3).map((n, i) => {
      const r = resolveName(n);
      const l = EVENT_TYPES[DEFAULT_EVENT_TYPE].lifts[i];
      return { slot: l ? l.slot : 'squat',
               leaf: r ? r.leaf : completeLeaf(customMovementFor(n), null) };
    });
  }
