export function slewLiftFor(leaf) {
  if (!leaf || !window.Slew) return null;
  for (const [test, id] of SLEW_LIFT) { try { if (test(leaf)) return id; } catch (e) { /* keep looking */ } }
  return null;
}
export function mvtFor(liftId) {
  const s = (S.settings.slewProfiles || {})[liftId] || {};
  const prior = Slew.defaultProfile(liftId).v0;
  const obs = (s.v0Obs || []).map(o => o.v).filter(v => v > 0);
  if (!obs.length) return s.v0Observed > 0 ? s.v0Observed : prior;   // before D1: one stored observation
  return (MVT_PRIOR_WEIGHT * prior + obs.reduce((a, b) => a + b, 0)) / (MVT_PRIOR_WEIGHT + obs.length);
}
export function lvFit(points) {
  const all = (points || []).filter(p => p.place !== 'pocket' && p.kg > 0 && p.v > 0);
  if (all.length < 3) return null;
  const { keep: pts, out } = lvOutliers(all);
  const kgs = pts.map(p => p.kg), maxKg = Math.max(...kgs), minKg = Math.min(...kgs);
  if ((maxKg - minKg) / maxKg < 0.15) return null;   // too narrow a ramp to draw a line through
  const { a, b, rse } = lvLine(pts);
  if (!(b < 0)) return null;                          // faster as it gets heavier: a bad recording
  return { a, b, n: pts.length, rse, heavy: maxKg, light: minKg, out };
}
/* A point keeps the weight of the set it was measured on. If that set's weight
   is corrected afterwards, the point follows it — otherwise the line is drawn
   through a weight that was never lifted. */
export function lvSync(e) {
  const pts = (e && e.lvp && e.lvp.points) || [];
  pts.forEach(p => {
    const s = e.sets && e.sets[p.si];
    if (s && s.vbt && s.vbt.at === p.at && s.w > 0) p.kg = s.w;
  });
}
export function lvDay(e) {
  lvSync(e);
  const f = lvFit(e && e.lvp && e.lvp.points);
  const liftId = e && e.leaf ? slewLiftFor(e.leaf) : null;
  if (!f || !liftId) return null;
  const mvt = mvtFor(liftId);
  const mid = (mvt - f.a) / f.b;
  if (!(mid > f.heavy)) return null;                  // the line says the heaviest warm-up was already a max: not believable
  const pctHeavy = f.heavy / mid * 100;
  if (pctHeavy < 35) return null;                     // nearly flat: reaching a max from here is guesswork
  const half = 4 + (f.rse / Math.abs(f.b)) / mid * 100 + Math.max(0, 80 - pctHeavy) * 0.5;
  return { mid, lo: mid * (1 - half / 100), hi: mid * (1 + half / 100), half, pctHeavy, mvt, fit: f, liftId };
}
export function vbtDayE1(key) {
  const a = S.active;
  if (!a || a.date !== today()) return null;
  const e = a.exercises.find(x => x.leaf && x.lvp && exKey(x) === key);
  const d = e && lvDay(e);
  return d ? d.mid : null;
}
/* ---------------- shareable session card ----------------
   Two cards, both drawn by hand to a canvas at 1080 wide so they land as real
   images rather than screenshots of a phone. Quick is a square with the totals
   — the one for a story. Full grows with the session: every set, then what
   the session asked of each muscle and how hard. No external fonts or
   libraries: the artifact sandbox blocks outside requests and a missing font
   would silently ruin the layout. */
export const CARD = {
  bg: '#0d0f14', tile: '#171c26', accent: '#ff5c35', text: '#e8ecf3', dim: '#8a93a5', line: '#252c3a',
  gold: '#ffc542', goldBg: 'rgba(255,197,66,.09)', warm: '#546074',
  light: '#3b7ddd', moderate: '#4fb477', hard: '#ff5c35',
};

/* ---------------- load-velocity maths (moved in from vbt.js, E17 phase 5) ---------------- */
/* Slew's nine profiles are VELOCITY-PROFILE BUCKETS, not exercises — "Row /
   pulldown" and "Machine (stack)" each cover a great many Ironlog leaves. So
   the mapping only ever runs leaf -> profile, never back, and anything with no
   sensible bucket gets measured without an effort estimate rather than being
   forced into the nearest profile. A wrong velocity profile produces a
   confident wrong RPE, which is worse than no RPE. */
export const SLEW_LIFT = [
  [l => l.movement === 'goblet-squat', 'Goblet squat'],
  [l => /squat/.test(l.movement) && l.equipment === 'smith', 'Squat (Smith)'],
  [l => /^(back-squat|front-squat|box-squat|pause-squat|safety-bar-squat)$/.test(l.movement), 'Squat (free bar)'],
  [l => /bench-press|larsen-press/.test(l.movement), 'Bench press'],
  [l => /deadlift/.test(l.movement) && l.equipment === 'trap_bar', 'Deadlift (trap)'],
  [l => /deadlift|rack-pull/.test(l.movement), 'Deadlift (conv.)'],
  [l => /overhead-press|push-press|shoulder-press/.test(l.movement), 'Overhead press'],
  [l => /row|pulldown|pull-up|chin-up/.test(l.movement), 'Row / pulldown'],
  [l => l.equipment === 'machine' || l.equipment === 'plate_loaded_machine' || l.equipment === 'cable', 'Machine (stack)'],
];
/* The minimum velocity threshold in use: the population prior shrunk toward
   what this lifter has actually failed at — (3·prior + Σobs) / (3 + n), so
   one odd set can't move it far. Written back as v0Observed so Slew's own
   estimator reads the same number. */
export const MVT_PRIOR_WEIGHT = 3;
/* ============================================================
   VBT PROFILE — roadmap D1, r&d/specs/vbt-overhaul-spec.md
   Profile mode: each measured warm-up is a (load, best-rep speed) point; a
   straight line through them meets the lift's minimum velocity threshold at
   the day's e1RM, shown as a range because a phone is not a transducer.
   Pocket readings are shown but never fitted.
   ============================================================ */
export function lvLine(pts) {
  const n = pts.length, mx = pts.reduce((a, p) => a + p.kg, 0) / n, my = pts.reduce((a, p) => a + p.v, 0) / n;
  let sxy = 0, sxx = 0;
  pts.forEach(p => { sxy += (p.kg - mx) * (p.v - my); sxx += (p.kg - mx) ** 2; });
  const b = sxx ? sxy / sxx : 0, a = my - b * mx;
  const rse = n > 2 ? Math.sqrt(pts.reduce((s, p) => s + (p.v - (a + b * p.kg)) ** 2, 0) / (n - 2)) : 0;
  return { a, b, rse };
}
export function lvOutliers(pts) {
  let keep = pts.slice();
  const out = [];
  while (keep.length > 3) {
    const sus = new Set();
    keep.forEach(p => keep.forEach(q => { if (q.kg > p.kg && q.v > p.v + LV_SLACK) { sus.add(p); sus.add(q); } }));
    if (!sus.size) break;
    let best = null;
    sus.forEach(p => {
      const rest = keep.filter(x => x !== p), f = lvLine(rest);
      if (!best || f.rse < best.rse) best = { p, rse: f.rse };
    });
    keep = keep.filter(x => x !== best.p);
    out.push(best.p);
  }
  return { keep, out };
}

/* ---------------- load-velocity tolerance (moved in from vbt.js) ---------------- */
/* Outliers: heavier can't be faster. A point more than LV_SLACK m/s faster
   than a lighter one breaks that — usually a first warm-up rep that wasn't
   moved with intent, or the next one ramped up. Of the points in such a clash,
   the one whose removal leaves the tightest line is left out; repeat while a
   clash remains and more than three points are left. Points that only bend
   the line (the heaviest warm-up slowing down a lot) are real and stay. */
export const LV_SLACK = 0.05;

/* ---------------- program names (moved in from coach.js) ---------------- */
export function programName(id) {
  return PROGRAM_NAMES[id] || (S.programNames || {})[id] || (PROGRAM_MANIFEST && id === PROGRAM_MANIFEST.id ? PROGRAM_MANIFEST.name : null)
    || (S.coach && S.coach.plan && S.coach.planProg === id ? `Coach · ${S.coach.plan.name}` : null)
    || (String(id).startsWith('coach-') ? 'Coach plan' : String(id).startsWith('import-') ? 'Imported plan' : id);
}

/* ---------------- body composition and bar-speed text (moved in, E17 phase 5) ---------------- */
export function caliperCalc(t) {
  const M = CAL_METHODS[t.method];
  if (!M) return null;
  const sites = M.sites(t.sex);
  const means = sites.map(s => { const r = ((t.mm || {})[s] || []).filter(x => x > 0); return r.length ? mean(r) : null; });
  if (means.some(x => x == null)) return { sites, means, complete: false };
  const sum = means.reduce((a, b) => a + b, 0);
  const bd = M.bd(sum, t.age || 0, t.sex);
  const bf = siri(bd);
  const w = weightNear(t.date);
  return { sites, means, complete: true, sum, bd, bf, odd: !(bf >= 3 && bf <= 50), young: t.method === 'dw4' && t.age < 17,
    wKg: w, fatKg: w ? w * bf / 100 : null, leanKg: w ? w * (1 - bf / 100) : null };
}
/* Every site's series: standard keys, then custom ones as "x:name". */
export function measSeries() {
  const out = {};
  [...S.measures].sort((a, b) => a.date < b.date ? -1 : 1).forEach(m => {
    Object.entries(m.cm || {}).forEach(([k, v]) => { if (v > 0) (out[k] = out[k] || []).push({ date: m.date, v, id: m.id }); });
    Object.entries(m.custom || {}).forEach(([k, v]) => { if (v > 0) (out['x:' + k] = out['x:' + k] || []).push({ date: m.date, v, id: m.id }); });
  });
  return out;
}
/* "RIR 3", or "RIR 6+" when the estimate is only a floor. */
export function vbtRirText(e) { return `${nice(rpeToRir(e.rpe))}${e.atLeast ? '+' : ''}`; }

/* ---------------- body composition maths (moved in from health.js) ---------------- */
export const CAL_METHODS = {
  jp3: { name: 'Jackson–Pollock 3-site', short: 'JP3',
    sites: sex => sex === 'female' ? ['triceps', 'suprailiac', 'thigh'] : ['chest', 'abdomen', 'thigh'],
    bd: (s, age, sex) => sex === 'female'
      ? 1.0994921 - 0.0009929 * s + 0.0000023 * s * s - 0.0001392 * age
      : 1.10938 - 0.0008267 * s + 0.0000016 * s * s - 0.0002574 * age },
  jp7: { name: 'Jackson–Pollock 7-site', short: 'JP7',
    sites: () => ['chest', 'midaxillary', 'triceps', 'subscapular', 'abdomen', 'suprailiac', 'thigh'],
    bd: (s, age, sex) => sex === 'female'
      ? 1.097 - 0.00046971 * s + 0.00000056 * s * s - 0.00012828 * age
      : 1.112 - 0.00043499 * s + 0.00000055 * s * s - 0.00028826 * age },
  dw4: { name: 'Durnin–Womersley 4-site', short: 'DW4',
    sites: () => ['biceps', 'triceps', 'subscapular', 'suprailiac'],
    bd: (s, age, sex) => {
      const bands = DW_BANDS[sex === 'female' ? 'female' : 'male'];
      const b = bands.filter(x => age >= x[0]).pop() || bands[0];
      return b[1] - b[2] * Math.log10(s);
    } },
};
export const siri = bd => 495 / bd - 450;
export const mean = a => a.reduce((x, y) => x + y, 0) / a.length;
/* The nearest check-in weight within three days of a date, or null. */
export function weightNear(date) {
  let best = null;
  S.checkins.forEach(c => {
    if (!(c.weight > 0)) return;
    const d = Math.abs(daysBetween(c.date, date));
    if (d <= 3 && (!best || d < best.d)) best = { d, kg: c.weight };
  });
  return best ? best.kg : null;
}

/* ---------------- Durnin–Womersley bands (moved in from health.js) ---------------- */
/* Durnin & Womersley (1974), [c, m] by age band. */
export const DW_BANDS = {
  male: [[17, 1.1620, 0.0630], [20, 1.1631, 0.0632], [30, 1.1422, 0.0544], [40, 1.1620, 0.0700], [50, 1.1715, 0.0779]],
  female: [[17, 1.1549, 0.0678], [20, 1.1599, 0.0717], [30, 1.1423, 0.0632], [40, 1.1333, 0.0612], [50, 1.1339, 0.0645]],
};

/* ---------------- per-side imbalance card and set shape (moved in from workout.js) ---------------- */
/* One of the B1 shapes (not plain reps, not a hold)? */
export function shapeKind(e) { const k = kindOf(e); return k !== 'reps' && k !== 'time'; }
export function imbalanceBlock(key) {
  const rows = imbalanceFor(key);
  if (!rows.length) return '';
  const last = rows.slice(-12).reverse(), recent = rows.slice(-6);
  const side = k => k === 'L' ? 'Left' : 'Right';
  const cnt = k => recent.filter(r => r.weak === k).length;
  const avg = recent.reduce((a, r) => a + r.gap, 0) / recent.length;
  const lead = cnt('L') === cnt('R') ? null : cnt('L') > cnt('R') ? 'L' : 'R';
  const line = avg < 3 ? `Even — average gap ${avg.toFixed(0)}% over the last ${recent.length}`
    : `${lead ? `${side(lead)} weaker in ${cnt(lead)} of the last ${recent.length}` : 'No side consistently weaker'} · average gap ${avg.toFixed(0)}%`;
  return `<div class="eyebrow" style="margin:16px 0 4px">Imbalance · left vs right</div>
    <div class="sub" style="margin-bottom:6px">${line}</div>
    <div class="card tight"><div class="row sub" style="gap:10px;font-size:11px"><span style="width:64px"></span><span class="grow row between"><span>◂ left stronger</span><span>right stronger ▸</span></span><span style="width:92px"></span></div>${last.map(r => {
      const wd = Math.min(50, r.gap * 2.5);   // 20% fills a half
      return `<div class="row" style="gap:10px;padding:4px 0;align-items:center" data-hist-wo="${esc(r.id)}">
        <span class="sub" style="width:64px">${fmtDate(r.date, { day: 'numeric', month: 'short' })}</span>
        <div class="imbar" aria-hidden="true"><i style="${r.signed >= 0 ? 'right:50%' : 'left:50%'};width:${wd}%"></i></div>
        <span class="mono sub" style="width:92px;text-align:right">${r.weak ? `${side(r.weak)} −${r.gap.toFixed(0)}%` : 'even'}</span>
      </div>`;
    }).join('')}</div>
    <div class="sub" style="margin-top:4px">The bar leans toward the stronger side. Under 3% counts as even.</div>`;
}

/* ---------------- which PRs a variant split would move (moved in from movement.js) ---------------- */
/* Which completed entries now sit in their own PR line (D10), and what that
   did to the raw lift's best: before = the old shared pool, after = without
   them. Read-only; feeds the exercise data check and the one-time notice. */
export function prPoolMoves(st) {
  const pools = {};
  (st.workouts || []).filter(w => w.status === 'completed').forEach(wo => (wo.exercises || []).forEach(e => {
    if (!e.leaf || !inRepsPool(e)) return;
    const k = exKey(e);
    if (!keyPR(k).length) return;
    (pools[k] = pools[k] || { key: k, entries: 0 }).entries++;
  }));
  const out = Object.values(pools).map(p => {
    const raw = leafKey(keyLeaf(p.key)) + p.key.slice(p.key.split('|')[0].length);
    const own = statsFor(p.key), rest = statsFor(raw);
    return { ...p, raw, label: leafName(p.key), rawName: leafName(raw), best: own ? own.best.e1 : 0, rawAfter: rest ? rest.best.e1 : 0 };
  });
  // the old shared pool held every split pool of that lift at once
  out.forEach(p => { p.rawBefore = Math.max(p.rawAfter, ...out.filter(q => q.raw === p.raw).map(q => q.best)); });
  return out.sort((a, b) => b.entries - a.entries);
}
